UPDATE account
SET display_name = CASE id
    WHEN '11111111-1111-1111-1111-111111110001' THEN '광주광산경찰서 수완지구대 경위 김도현'
    WHEN '11111111-1111-1111-1111-111111110002' THEN '광주광산경찰서 수완지구대 경사 박민수'
    WHEN '11111111-1111-1111-1111-111111110003' THEN '광주광산경찰서 수완지구대 순경 이준호'
    WHEN '11111111-1111-1111-1111-111111110004' THEN '광주경찰청 여성청소년과 실종팀 경감 정서윤'
    WHEN '11111111-1111-1111-1111-111111110005' THEN '광주경찰청 여성청소년과 실종팀 경사 최지훈'
    WHEN '11111111-1111-1111-1111-111111110006' THEN '광주경찰청 기동대 경위 강현우'
    WHEN '11111111-1111-1111-1111-111111110007' THEN '광주경찰청 기동대 경사 윤태영'
    WHEN '11111111-1111-1111-1111-111111110008' THEN '광주경찰청 기동대 순경 오민재'
    WHEN '11111111-1111-1111-1111-111111110009' THEN '광주광산경찰서 수완지구대 순경 한지민'
    ELSE display_name
END,
updated_at = CURRENT_TIMESTAMP
WHERE id IN (
    '11111111-1111-1111-1111-111111110001',
    '11111111-1111-1111-1111-111111110002',
    '11111111-1111-1111-1111-111111110003',
    '11111111-1111-1111-1111-111111110004',
    '11111111-1111-1111-1111-111111110005',
    '11111111-1111-1111-1111-111111110006',
    '11111111-1111-1111-1111-111111110007',
    '11111111-1111-1111-1111-111111110008',
    '11111111-1111-1111-1111-111111110009'
);

UPDATE police_phone
SET display_name = CASE id
    WHEN '00000000-0000-0000-0000-000000000201' THEN '수완지구대 지휘 단말'
    WHEN '50000000-0000-0000-0000-000000000001' THEN '수완지구대 순찰차 단말'
    WHEN '00000000-0000-0000-0000-000000000101' THEN '수완지구대 현장 단말'
    WHEN '00000000-0000-0000-0000-000000000204' THEN '여성청소년과 실종팀 지휘 단말'
    WHEN '00000000-0000-0000-0000-000000000205' THEN '여성청소년과 실종팀 현장 단말'
    WHEN '00000000-0000-0000-0000-000000000206' THEN '기동대 지휘 단말'
    WHEN '00000000-0000-0000-0000-000000000207' THEN '기동대 차량 단말'
    WHEN '00000000-0000-0000-0000-000000000208' THEN '기동대 현장 단말'
    WHEN '00000000-0000-0000-0000-000000000301' THEN '미배정 폴리폰 단말'
    ELSE display_name
END,
updated_at = CURRENT_TIMESTAMP
WHERE id IN (
    '00000000-0000-0000-0000-000000000201',
    '50000000-0000-0000-0000-000000000001',
    '00000000-0000-0000-0000-000000000101',
    '00000000-0000-0000-0000-000000000204',
    '00000000-0000-0000-0000-000000000205',
    '00000000-0000-0000-0000-000000000206',
    '00000000-0000-0000-0000-000000000207',
    '00000000-0000-0000-0000-000000000208',
    '00000000-0000-0000-0000-000000000301'
);
